 S('«Нан» — по-русски?', 'хлеб', 'мясо', 'молоко', 'мёд'),
 S('«Honey» по-кыргызски?', 'бал', 'сүт', 'эт', 'туз', w=2, e='Не путайте с русским «бал» (танцевальный вечер): по-кыргызски «бал» — мёд.', img='en:Honey'),
 S('«Күн» значит…', 'и «солнце», и «день» — sun, day', 'только «луна»', 'только «год»', '«звезда»', e='Как и «ай» — это и «луна», и «месяц».'),
 S('Передышка без очков: «Рахмат» по-английски…', 'Thank you', 'Hello', 'Sorry', 'Goodbye', w=0),
 M('Какие пары переведены правильно?', ['*көл — lake', '*кар — snow', '*жол — road', '*бала — child', 'көз — ear', 'баш — foot']),
 S('«Ear» по-кыргызски?', 'кулак', 'көз', 'мурун', 'ооз', e='Не путайте с русским «кулак»: по-кыргызски «кулак» — это ухо, а кулак — «муштум».', img='en:Ear'),
 S('«Eye» по-кыргызски?', 'көз', 'кол', 'бут', 'баш'),
 S('Как по-английски «мугалим»?', 'teacher', 'student', 'doctor', 'driver'),
 W('Соберите по-английски слово «жылдыз».', 'star'),
 W('Соберите по-кыргызски слово «winter».', 'кыш', img='en:Winter'),
 T('Переведите на английский «Мен студентмин». Три слова.', ['I am a student', 'I am a student.', "I'm a student", 'i am a student']),
 S('Как сказать по-кыргызски «Как дела?»?', 'Иштер кандай?', 'Атың ким?', 'Канча турат?', 'Кайда барасың?'),
 S('«Канча турат?» значит…', 'Сколько стоит? — How much is it?', 'Где ты живёшь? — Where do you live?', 'Как тебя зовут? — What is your name?', 'Который час? — What time is it?'),
 S('Что значит «Менин атым Айпери»?', 'Меня зовут Айпери — My name is Aiperi', 'Моя лошадь — Айпери', 'Мой отец — Айпери', 'Я иду к Айпери'),
